# frozen_string_literal: true

require 'digest'

class MetricsGlossary
  #= Digests of the source of Ruby methods marked `formula: true`, and of the
  # value of every constant the glossary points at, recorded in
  # docs/metrics/fingerprints.yml when someone has checked that the glossary
  # still describes them. When one changes, the checker fails until the
  # entries that point at it are re-read and `bin/rails metrics:accept` is run.
  class Fingerprints
    PATH = MetricsGlossary::DIR.join('fingerprints.yml')
    HEADER = <<~TEXT
      # Generated by `bin/rails metrics:accept`. Do not edit by hand.
      # Each digest is of a `formula: true` method's source or a constant's value,
      # as of the last time someone checked that the glossary entries in
      # docs/metrics/ that point at it still describe it.
    TEXT

    def self.digest(source)
      Digest::SHA256.hexdigest(source)[0, 16]
    end

    def initialize(glossary, path = PATH)
      @glossary = glossary
      @path = path
    end

    def stored
      @stored ||= File.exist?(@path) ? YAML.safe_load_file(@path) || {} : {}
    end

    # { 'WordCount.from_characters' => digest } for every fingerprinted ref
    # that resolves. Unresolvable refs are reported by the checker instead.
    def current
      @current ||= fingerprinted_refs.to_h do |ref|
        [ref.target, self.class.digest(ref.fingerprint_source)]
      end.sort.to_h
    end

    # { target => [metric and divergence keys that point at it] }, for naming
    # the entries to re-read in messages.
    def owners_by_target
      owners = Hash.new { |hash, target| hash[target] = [] }
      @glossary.metrics.each_value { |m| add_owners(owners, m.key, m.implementations) }
      @glossary.divergences.each_value { |d| add_owners(owners, d.key, d.code) }
      owners
    end

    def changed
      current.keys.select { |target| stored.key?(target) && stored[target] != current[target] }
    end

    def unrecorded
      current.keys - stored.keys
    end

    def stale
      stored.keys - current.keys
    end

    def write!
      File.write(@path, HEADER + current.to_yaml.delete_prefix("---\n"))
    end

    private

    def fingerprinted_refs
      @glossary.code_refs.select { |ref| ref.error.nil? && ref.fingerprinted? }.uniq(&:target)
    end

    def add_owners(owners, key, refs)
      refs.map(&:target).uniq.each do |target|
        owners[target] << key if current.key?(target)
      end
    end
  end
end
